package checkpoint

import (
	"context"
	"crypto/sha256"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/validation"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/redact"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// WriteCommitted writes a committed checkpoint to both v2 refs:
//   - /main: metadata and prompts (no raw transcript or content hash)
//   - /full/current: raw transcript + content hash (replaces previous content)
//
// This is the public entry point for v2 dual-writes. The session index is
// determined from the /main ref and passed to the /full/current write to
// keep both refs consistent.
func (s *V2GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
	// Validate upfront before any writes to avoid partial ref updates
	if err := validateWriteOpts(opts); err != nil {
		return err
	}

	sessionIndex, err := s.writeCommittedMain(ctx, opts)
	if err != nil {
		return fmt.Errorf("v2 /main write failed: %w", err)
	}

	if err := s.writeCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
		return fmt.Errorf("v2 /full/current write failed: %w", err)
	}

	return nil
}

// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
// Called at stop time to finalize checkpoints with the complete session transcript.
//
// On /main: replaces prompts (transcript is not stored there).
// On /full/current: replaces the raw transcript (if provided).
//
// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
	if opts.CheckpointID.IsEmpty() {
		return errors.New("invalid update options: checkpoint ID is required")
	}

	sessionIndex, err := s.updateCommittedMain(ctx, opts)
	if err != nil {
		return fmt.Errorf("v2 /main update failed: %w", err)
	}

	if len(opts.Transcript) > 0 {
		if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
			return fmt.Errorf("v2 /full/current update failed: %w", err)
		}
	}

	return nil
}

// updateCommittedMain updates prompts on the /main ref for an existing checkpoint.
// Returns the session index for coordination with /full/current.
func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
	refName := plumbing.ReferenceName(paths.V2MainRefName)
	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return 0, ErrCheckpointNotFound
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()

	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return 0, err
	}

	rootMetadataPath := basePath + paths.MetadataFileName
	entry, exists := entries[rootMetadataPath]
	if !exists {
		return 0, ErrCheckpointNotFound
	}

	summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
	if err != nil {
		return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
	}
	if len(summary.Sessions) == 0 {
		return 0, ErrCheckpointNotFound
	}

	// Find session index by ID, fall back to latest
	sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
	if sessionIndex >= len(summary.Sessions) {
		// findSessionIndex returns next-available when not found; fall back to latest
		sessionIndex = len(summary.Sessions) - 1
		logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
			slog.String("session_id", opts.SessionID),
			slog.String("checkpoint_id", string(opts.CheckpointID)),
			slog.Int("fallback_index", sessionIndex),
		)
	}

	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)

	if len(opts.Prompts) > 0 {
		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return 0, fmt.Errorf("failed to create prompt blob: %w", err)
		}
		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
			Name: sessionPath + paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return 0, err
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
		return 0, err
	}

	return sessionIndex, nil
}

// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
// on /full/current while preserving other checkpoints' transcripts in the tree.
func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
	if err := s.ensureRef(refName); err != nil {
		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
	}

	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return err
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()
	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)

	// Read existing entries and replace transcript for this checkpoint only
	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return err
	}

	// Clear existing transcript entries at this session path before writing new ones
	for key := range entries {
		if strings.HasPrefix(key, sessionPath) {
			delete(entries, key)
		}
	}

	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
	if err != nil {
		return err
	}

	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
		return err
	}

	// Splice into existing root tree (preserves other checkpoints' transcripts)
	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return err
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
}

// writeCommittedMain writes metadata entries to the /main ref.
// This includes session metadata and prompts — but NOT the raw transcript
// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
	refName := plumbing.ReferenceName(paths.V2MainRefName)
	if err := s.ensureRef(refName); err != nil {
		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
	}

	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return 0, err
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()

	// Read existing entries at this checkpoint's shard path
	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return 0, err
	}

	// Build main session entries (metadata, prompts — no transcript or content hash)
	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
	if err != nil {
		return 0, err
	}

	// Splice entries into root tree
	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return 0, err
	}

	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
		return 0, err
	}
	return sessionIndex, nil
}

// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
// Returns the session index used, for coordination with writeCommittedFullTranscript.
func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
	// Read existing summary to get current session count
	var existingSummary *CheckpointSummary
	metadataPath := basePath + paths.MetadataFileName
	if entry, exists := entries[metadataPath]; exists {
		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
		if err == nil {
			existingSummary = existing
		}
	}

	// Determine session index
	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)

	// Write session files (metadata and prompts — no transcript or content hash)
	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
	if err != nil {
		return 0, err
	}

	// Build the sessions array
	var sessions []SessionFilePaths
	if existingSummary != nil {
		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
		copy(sessions, existingSummary.Sessions)
	} else {
		sessions = make([]SessionFilePaths, 1)
	}
	sessions[sessionIndex] = sessionFilePaths

	// Write root CheckpointSummary
	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
		return 0, err
	}
	return sessionIndex, nil
}

// writeMainSessionToSubdirectory writes a single session's metadata and prompts
// to a session subdirectory (0/, 1/, 2/, … indexed by session order within the
// checkpoint). Unlike the v1 equivalent, this does NOT write the raw transcript
// (full.jsonl) or content hash (content_hash.txt) — those go to /full/current.
func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
	filePaths := SessionFilePaths{}

	// Clear existing entries at this session path
	for key := range entries {
		if strings.HasPrefix(key, sessionPath) {
			delete(entries, key)
		}
	}

	// Write prompts
	if len(opts.Prompts) > 0 {
		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return filePaths, err
		}
		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
			Name: sessionPath + paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
	}

	// Write session metadata
	sessionMetadata := CommittedMetadata{
		CheckpointID:                opts.CheckpointID,
		SessionID:                   opts.SessionID,
		Strategy:                    opts.Strategy,
		CreatedAt:                   time.Now().UTC(),
		Branch:                      opts.Branch,
		CheckpointsCount:            opts.CheckpointsCount,
		FilesTouched:                opts.FilesTouched,
		Agent:                       opts.Agent,
		Model:                       opts.Model,
		TurnID:                      opts.TurnID,
		IsTask:                      opts.IsTask,
		ToolUseID:                   opts.ToolUseID,
		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
		TokenUsage:                  opts.TokenUsage,
		SessionMetrics:              opts.SessionMetrics,
		InitialAttribution:          opts.InitialAttribution,
		Summary:                     redactSummary(opts.Summary),
		CLIVersion:                  versioninfo.Version,
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
	if err != nil {
		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return filePaths, err
	}
	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
		Name: sessionPath + paths.MetadataFileName,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName

	return filePaths, nil
}

// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		return err
	}
	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
		Name: sessionPath + paths.ContentHashFileName,
		Mode: filemode.Regular,
		Hash: hashBlob,
	}
	return nil
}

// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
// Transcripts accumulate across checkpoints — each write splices into the existing
// tree. Generation metadata (generation.json) at the tree root is updated on every
// write with the new checkpoint ID and timestamps.
//
// sessionIndex is the session slot (0-based), determined by the caller to stay
// consistent with the /main ref's session numbering.
// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
	transcript := opts.Transcript
	if len(transcript) == 0 && opts.TranscriptPath != "" {
		var readErr error
		transcript, readErr = os.ReadFile(opts.TranscriptPath)
		if readErr != nil {
			transcript = nil
		}
	}
	if len(transcript) == 0 {
		return nil // No transcript to write
	}

	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
	if err := s.ensureRef(refName); err != nil {
		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
	}

	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return err
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()
	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)

	// Read existing entries at this checkpoint's shard path
	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return err
	}

	// Clear existing entries at this session path before writing new ones
	for key := range entries {
		if strings.HasPrefix(key, sessionPath) {
			delete(entries, key)
		}
	}

	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
	if err != nil {
		return err
	}

	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
		return err
	}

	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return err
	}

	// Update generation.json at the tree root with the new checkpoint ID and timestamps.
	// This reads from the pre-splice root tree (to get existing metadata) and writes
	// into the post-splice tree (which already has the shard directories).
	gen, err := s.updateGenerationForWrite(rootTreeHash, opts.CheckpointID, time.Now().UTC())
	if err != nil {
		return fmt.Errorf("failed to update generation metadata: %w", err)
	}
	newTreeHash, err = s.addGenerationToRootTree(newTreeHash, gen)
	if err != nil {
		return fmt.Errorf("failed to add generation.json to tree: %w", err)
	}

	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
		return err
	}

	// Check if rotation is needed after successful write.
	if len(gen.Checkpoints) >= s.maxCheckpoints() {
		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
			logging.Warn(ctx, "generation rotation failed",
				slog.String("error", rotErr.Error()),
				slog.Int("checkpoint_count", len(gen.Checkpoints)),
			)
			// Non-fatal: rotation failure doesn't invalidate the write
		}
	}

	return nil
}

// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
// Returns the redacted transcript bytes so the caller can compute the content hash.
func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
	// Redact secrets before chunking
	redacted, err := redact.JSONLBytes(transcript)
	if err != nil {
		return nil, fmt.Errorf("failed to redact transcript: %w", err)
	}

	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
	}

	for i, chunk := range chunks {
		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
		blobHash, err := CreateBlobFromContent(s.repo, chunk)
		if err != nil {
			return nil, err
		}
		entries[chunkPath] = object.TreeEntry{
			Name: chunkPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	return redacted, nil
}

// validateWriteOpts validates identifiers in WriteCommittedOptions.
func validateWriteOpts(opts WriteCommittedOptions) error {
	if opts.CheckpointID.IsEmpty() {
		return errors.New("invalid checkpoint options: checkpoint ID is required")
	}
	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	return nil
}

package strategy

import (
	"context"
	"fmt"
	"log/slog"
	"net/url"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6/plumbing"
)

// checkpointRemoteFetchTimeout is the timeout for fetching branches from the checkpoint URL.
const checkpointRemoteFetchTimeout = 30 * time.Second

// Git remote protocol identifiers.
const (
	protocolSSH   = "ssh"
	protocolHTTPS = "https"
)

// pushSettings holds the resolved push configuration from a single settings load.
type pushSettings struct {
	// remote is the git remote name to use for pushing (the user's push remote).
	remote string
	// checkpointURL is the derived URL for pushing checkpoint branches.
	// When set, checkpoint/trails branches are pushed directly to this URL
	// instead of the remote name. Empty means use the remote name.
	checkpointURL string
	// pushDisabled is true if push_sessions is explicitly set to false.
	pushDisabled bool
}

// pushTarget returns the target to use for git push/fetch commands for checkpoint branches.
// If a checkpoint URL is configured, returns that; otherwise returns the remote name.
func (ps *pushSettings) pushTarget() string {
	if ps.checkpointURL != "" {
		return ps.checkpointURL
	}
	return ps.remote
}

// hasCheckpointURL returns true if a dedicated checkpoint URL is configured.
func (ps *pushSettings) hasCheckpointURL() bool {
	return ps.checkpointURL != ""
}

// resolvePushSettings loads settings once and returns the resolved push config.
// If a structured checkpoint_remote is configured (e.g., {"provider": "github", "repo": "org/repo"}):
//   - Derives the checkpoint URL from the push remote's protocol (SSH vs HTTPS)
//   - Skips if the push remote owner differs from the checkpoint repo owner (fork detection)
//   - If a checkpoint branch doesn't exist locally, attempts to fetch it from the URL
//
// The push itself handles failures gracefully (doPushBranch warns and continues),
// so no reachability check is needed here.
func resolvePushSettings(ctx context.Context, pushRemoteName string) pushSettings {
	s, err := settings.Load(ctx)
	if err != nil {
		return pushSettings{remote: pushRemoteName}
	}

	ps := pushSettings{
		remote:       pushRemoteName,
		pushDisabled: s.IsPushSessionsDisabled(),
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return ps
	}

	// Get the push remote URL for protocol detection and fork detection
	pushRemoteURL, err := getRemoteURL(ctx, pushRemoteName)
	if err != nil {
		logging.Debug(ctx, "checkpoint-remote: could not get push remote URL, skipping",
			slog.String("remote", pushRemoteName),
			slog.String("error", err.Error()),
		)
		return ps
	}

	// Parse the push remote URL once for both fork detection and URL derivation
	pushInfo, err := parseGitRemoteURL(pushRemoteURL)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not parse push remote URL",
			slog.String("remote", pushRemoteName),
			slog.String("error", err.Error()),
		)
		return ps
	}

	// Fork detection: compare owners
	checkpointOwner := config.Owner()
	if pushInfo.owner != "" && checkpointOwner != "" && !strings.EqualFold(pushInfo.owner, checkpointOwner) {
		logging.Debug(ctx, "checkpoint-remote: push remote owner differs from checkpoint remote owner, skipping (fork detected)",
			slog.String("push_owner", pushInfo.owner),
			slog.String("checkpoint_owner", checkpointOwner),
		)
		return ps
	}

	// Derive checkpoint URL using same protocol as push remote
	checkpointURL, err := deriveCheckpointURLFromInfo(pushInfo, config)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not derive URL from push remote",
			slog.String("remote", pushRemoteName),
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ps
	}

	ps.checkpointURL = checkpointURL

	// If the checkpoint branch doesn't exist locally, try to fetch it from the URL.
	// This is a one-time operation — once the branch exists locally, subsequent pushes
	// skip the fetch entirely. Only fetch the metadata branch; trails are always pushed
	// to the user's push remote, not the checkpoint remote.
	if err := fetchMetadataBranchIfMissing(ctx, checkpointURL); err != nil {
		logging.Warn(ctx, "checkpoint-remote: failed to fetch metadata branch",
			slog.String("error", err.Error()),
		)
	}

	return ps
}

// ResolveRemoteRepo returns the host, owner, and repo name for the given git remote.
// It parses the remote URL (SSH or HTTPS) and extracts the components.
// For example, git@github.com:org/my-repo.git returns ("github.com", "org", "my-repo").
func ResolveRemoteRepo(ctx context.Context, remoteName string) (host, owner, repo string, err error) {
	rawURL, err := getRemoteURL(ctx, remoteName)
	if err != nil {
		return "", "", "", fmt.Errorf("get remote URL for %q: %w", remoteName, err)
	}
	info, err := parseGitRemoteURL(rawURL)
	if err != nil {
		return "", "", "", fmt.Errorf("parse remote URL: %w", err)
	}
	return info.host, info.owner, info.repo, nil
}

// gitRemoteInfo holds parsed components of a git remote URL.
type gitRemoteInfo struct {
	protocol string // "ssh" or "https"
	host     string // e.g., "github.com"
	owner    string // e.g., "org"
	repo     string // e.g., "my-repo" (without .git)
}

// parseGitRemoteURL parses a git remote URL into its components.
// Supports:
//   - SSH SCP format: git@github.com:org/repo.git
//   - HTTPS format: https://github.com/org/repo.git
//   - SSH protocol format: ssh://git@github.com/org/repo.git
func parseGitRemoteURL(rawURL string) (*gitRemoteInfo, error) {
	rawURL = strings.TrimSpace(rawURL)

	// SSH SCP format: git@github.com:org/repo.git
	if strings.Contains(rawURL, ":") && !strings.Contains(rawURL, "://") {
		// Split on the first ":"
		parts := strings.SplitN(rawURL, ":", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid SSH URL: %s", redactURL(rawURL))
		}
		hostPart := parts[0] // e.g., "git@github.com"
		pathPart := parts[1] // e.g., "org/repo.git"

		host := hostPart
		if idx := strings.Index(host, "@"); idx >= 0 {
			host = host[idx+1:]
		}

		owner, repo, err := splitOwnerRepo(pathPart)
		if err != nil {
			return nil, err
		}

		return &gitRemoteInfo{protocol: protocolSSH, host: host, owner: owner, repo: repo}, nil
	}

	// URL format: https://github.com/org/repo.git or ssh://git@github.com/org/repo.git
	u, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %s", redactURL(rawURL))
	}

	protocol := u.Scheme
	if protocol == "" {
		return nil, fmt.Errorf("no protocol in URL: %s", redactURL(rawURL))
	}
	host := u.Hostname()

	// Path is like /org/repo.git — trim leading slash
	pathPart := strings.TrimPrefix(u.Path, "/")
	owner, repo, err := splitOwnerRepo(pathPart)
	if err != nil {
		return nil, err
	}

	return &gitRemoteInfo{protocol: protocol, host: host, owner: owner, repo: repo}, nil
}

// splitOwnerRepo splits "org/repo.git" into owner and repo (without .git suffix).
func splitOwnerRepo(path string) (string, string, error) {
	path = strings.TrimSuffix(path, ".git")
	parts := strings.SplitN(path, "/", 2)
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return "", "", fmt.Errorf("cannot parse owner/repo from path: %s", path)
	}
	return parts[0], parts[1], nil
}

// deriveCheckpointURL constructs a checkpoint remote URL using the same protocol
// as the push remote. For example, if push remote uses SSH, the checkpoint URL
// will also use SSH.
func deriveCheckpointURL(pushRemoteURL string, config *settings.CheckpointRemoteConfig) (string, error) {
	info, err := parseGitRemoteURL(pushRemoteURL)
	if err != nil {
		return "", fmt.Errorf("cannot parse push remote URL: %w", err)
	}
	return deriveCheckpointURLFromInfo(info, config)
}

// deriveCheckpointURLFromInfo constructs a checkpoint URL from already-parsed remote info.
func deriveCheckpointURLFromInfo(info *gitRemoteInfo, config *settings.CheckpointRemoteConfig) (string, error) {
	switch info.protocol {
	case protocolSSH:
		// SCP format: git@host:owner/repo.git
		return fmt.Sprintf("git@%s:%s.git", info.host, config.Repo), nil
	case protocolHTTPS:
		return fmt.Sprintf("https://%s/%s.git", info.host, config.Repo), nil
	default:
		return "", fmt.Errorf("unsupported protocol %q in push remote", info.protocol)
	}
}

// extractOwnerFromRemoteURL extracts the owner from a git remote URL.
// Returns empty string if the URL cannot be parsed.
func extractOwnerFromRemoteURL(rawURL string) string {
	info, err := parseGitRemoteURL(rawURL)
	if err != nil {
		return ""
	}
	return info.owner
}

// getRemoteURL returns the URL configured for a git remote.
func getRemoteURL(ctx context.Context, remoteName string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "remote", "get-url", remoteName)
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("remote %q not found", remoteName)
	}
	return strings.TrimSpace(string(output)), nil
}

// redactURL removes credentials from a URL for safe logging.
// Handles both HTTPS URLs with embedded credentials and general URLs.
func redactURL(rawURL string) string {
	u, err := url.Parse(rawURL)
	if err != nil {
		// For non-URL formats (SSH SCP), just return the host portion
		if idx := strings.Index(rawURL, "@"); idx >= 0 {
			if colonIdx := strings.Index(rawURL[idx:], ":"); colonIdx >= 0 {
				return rawURL[idx+1:idx+colonIdx] + ":***"
			}
		}
		return "<unparseable>"
	}
	u.User = nil
	u.RawQuery = ""
	host := u.Host
	path := u.Path
	return u.Scheme + "://" + host + path
}

// fetchMetadataBranchIfMissing fetches the metadata branch from a URL only if it doesn't exist locally.
// This avoids network calls on every push — once the branch exists locally, this is a no-op.
// Fetch failures are silently swallowed (returns nil): the push will handle creating the
// branch on the remote. Only fatal errors (opening repo, creating local branch) are returned.
func fetchMetadataBranchIfMissing(ctx context.Context, remoteURL string) error {
	branchName := paths.MetadataBranchName

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	// Check if branch already exists locally - if so, nothing to do
	branchRef := plumbing.NewBranchReferenceName(branchName)
	if _, err := repo.Reference(branchRef, true); err == nil {
		return nil // Branch exists locally, skip fetch
	}

	// Branch doesn't exist locally - try to fetch it from the URL.
	// Fetch to a temp ref to avoid polluting the remote-tracking namespace.
	fetchCtx, cancel := context.WithTimeout(ctx, checkpointRemoteFetchTimeout)
	defer cancel()

	tmpRef := "refs/entire-fetch-tmp/" + branchName
	refSpec := fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
	fetchCmd := exec.CommandContext(fetchCtx, "git", "fetch", "--no-tags", remoteURL, refSpec)
	fetchCmd.Stdin = nil
	fetchCmd.Env = append(os.Environ(),
		"GIT_TERMINAL_PROMPT=0", // Prevent interactive auth prompts
	)
	if err := fetchCmd.Run(); err != nil {
		// Fetch failed - remote may be unreachable or branch doesn't exist there yet.
		// Not fatal: push will create it on the remote when it succeeds.
		return nil
	}

	// Fetch succeeded - create local branch from the fetched ref
	fetchedRef, err := repo.Reference(plumbing.ReferenceName(tmpRef), true)
	if err != nil {
		// Fetch succeeded but ref not found - branch may not exist on remote
		return nil
	}

	newRef := plumbing.NewHashReference(branchRef, fetchedRef.Hash())
	if err := repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to create local branch from fetched ref: %w", err)
	}

	// Clean up the temp ref (best-effort, not critical if it fails)
	_ = repo.Storer.RemoveReference(plumbing.ReferenceName(tmpRef)) //nolint:errcheck // cleanup is best-effort

	logging.Info(ctx, "checkpoint-remote: fetched metadata branch from URL")
	return nil
}

package paths

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// Directory constants
const (
	EntireDir         = ".entire"
	EntireTmpDir      = ".entire/tmp"
	EntireMetadataDir = ".entire/metadata"
)

// Metadata file names
const (
	PromptFileName           = "prompt.txt"
	TranscriptFileName       = "full.jsonl"
	TranscriptFileNameLegacy = "full.log"
	MetadataFileName         = "metadata.json"
	CheckpointFileName       = "checkpoint.json"
	ContentHashFileName      = "content_hash.txt"
	SettingsFileName         = "settings.json"
)

// MetadataBranchName is the orphan branch used by manual-commit strategy to store metadata
const MetadataBranchName = "entire/checkpoints/v1"

// V2 ref names use custom refs under refs/entire/ (not refs/heads/).
// These are invisible in GitHub's branch UI and not fetched by default.
const (
	// V2MainRefName stores permanent metadata + compact transcripts.
	V2MainRefName = "refs/entire/checkpoints/v2/main"

	// V2FullCurrentRefName stores the active generation of raw transcripts.
	V2FullCurrentRefName = "refs/entire/checkpoints/v2/full/current"

	// V2FullRefPrefix is the common prefix for all /full/* refs (current + archived).
	V2FullRefPrefix = "refs/entire/checkpoints/v2/full/"

	// GenerationFileName is the metadata file at the root of each /full/* generation tree.
	GenerationFileName = "generation.json"
