// pushV2Refs pushes all v2 checkpoint refs to the target.
// Pushes /main, /full/current, and any archived /full/* generations.
func pushV2Refs(ctx context.Context, target string) {
	pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))
	pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName))

	// Push archived generations
	repo, err := OpenRepository(ctx)
	if err != nil {
		return
	}
	store := checkpoint.NewV2GitStore(repo)
	archived, err := store.ListArchivedGenerations()
	if err != nil {
		return
	}
	for _, gen := range archived {
		refName := plumbing.ReferenceName(paths.V2FullRefPrefix + gen)
		pushRefIfNeeded(ctx, target, refName)
	}
}
