package checkpoint

import (
	"fmt"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// V2GitStore provides checkpoint storage operations for the v2 ref layout.
// It writes to two custom refs under refs/entire/:
//   - /main: permanent metadata + compact transcripts
//   - /full/current: active generation of raw transcripts
//
// V2GitStore is separate from GitStore (v1) to keep concerns isolated
// and simplify future v1 removal. It composes GitStore internally to
// reuse ref-agnostic entry-building helpers (tree surgery, session
// indexing, summary aggregation).
type V2GitStore struct {
	repo *git.Repository
	gs   *GitStore // shared entry-building helpers (same package)

	// maxCheckpointsPerGeneration overrides the rotation threshold for testing.
	// Zero means use DefaultMaxCheckpointsPerGeneration.
	maxCheckpointsPerGeneration int
}

// maxCheckpoints returns the effective rotation threshold.
func (s *V2GitStore) maxCheckpoints() int {
	if s.maxCheckpointsPerGeneration > 0 {
		return s.maxCheckpointsPerGeneration
	}
	return DefaultMaxCheckpointsPerGeneration
}

// NewV2GitStore creates a new v2 checkpoint store backed by the given git repository.
func NewV2GitStore(repo *git.Repository) *V2GitStore {
	return &V2GitStore{
		repo: repo,
		gs:   &GitStore{repo: repo},
	}
}

// ensureRef ensures that a custom ref exists, creating an orphan commit
// with an empty tree if it does not.
func (s *V2GitStore) ensureRef(refName plumbing.ReferenceName) error {
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Already exists
	}

	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return fmt.Errorf("failed to build empty tree: %w", err)
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Initialize v2 ref", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create initial commit: %w", err)
	}

	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to set ref %s: %w", refName, err)
	}

	return nil
}

// getRefState returns the parent commit hash and root tree hash for a ref.
func (s *V2GitStore) getRefState(refName plumbing.ReferenceName) (parentHash, treeHash plumbing.Hash, err error) {
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit for ref %s: %w", refName, err)
	}

	return ref.Hash(), commit.TreeHash, nil
}

// updateRef creates a new commit on a ref with the given tree, updating the ref to point to it.
func (s *V2GitStore) updateRef(refName plumbing.ReferenceName, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) error {
	commitHash, err := CreateCommit(s.repo, treeHash, parentHash, message, authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("failed to create commit: %w", err)
	}

	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to update ref %s: %w", refName, err)
	}

	return nil
}

package checkpoint

import (
	"context"
	"crypto/sha256"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/validation"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/redact"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// WriteCommitted writes a committed checkpoint to both v2 refs:
//   - /main: metadata and prompts (no raw transcript or content hash)
//   - /full/current: raw transcript + content hash (replaces previous content)
//
// This is the public entry point for v2 dual-writes. The session index is
// determined from the /main ref and passed to the /full/current write to
// keep both refs consistent.
func (s *V2GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
	// Validate upfront before any writes to avoid partial ref updates
	if err := validateWriteOpts(opts); err != nil {
		return err
	}

	sessionIndex, err := s.writeCommittedMain(ctx, opts)
	if err != nil {
		return fmt.Errorf("v2 /main write failed: %w", err)
	}

	if err := s.writeCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
		return fmt.Errorf("v2 /full/current write failed: %w", err)
	}

	return nil
}

// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
// Called at stop time to finalize checkpoints with the complete session transcript.
//
// On /main: replaces prompts (transcript is not stored there).
// On /full/current: replaces the raw transcript (if provided).
//
// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
	if opts.CheckpointID.IsEmpty() {
		return errors.New("invalid update options: checkpoint ID is required")
	}

	sessionIndex, err := s.updateCommittedMain(ctx, opts)
	if err != nil {
		return fmt.Errorf("v2 /main update failed: %w", err)
	}

	if len(opts.Transcript) > 0 {
		if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
			return fmt.Errorf("v2 /full/current update failed: %w", err)
		}
	}

	return nil
}

// updateCommittedMain updates prompts on the /main ref for an existing checkpoint.
// Returns the session index for coordination with /full/current.
func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
	refName := plumbing.ReferenceName(paths.V2MainRefName)
	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return 0, ErrCheckpointNotFound
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()

	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return 0, err
	}

	rootMetadataPath := basePath + paths.MetadataFileName
	entry, exists := entries[rootMetadataPath]
	if !exists {
		return 0, ErrCheckpointNotFound
	}

	summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
	if err != nil {
		return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
	}
	if len(summary.Sessions) == 0 {
		return 0, ErrCheckpointNotFound
	}

	// Find session index by ID, fall back to latest
	sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
	if sessionIndex >= len(summary.Sessions) {
		// findSessionIndex returns next-available when not found; fall back to latest
		sessionIndex = len(summary.Sessions) - 1
		logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
			slog.String("session_id", opts.SessionID),
			slog.String("checkpoint_id", string(opts.CheckpointID)),
			slog.Int("fallback_index", sessionIndex),
		)
	}

	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)

	if len(opts.Prompts) > 0 {
		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return 0, fmt.Errorf("failed to create prompt blob: %w", err)
		}
		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
			Name: sessionPath + paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return 0, err
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
		return 0, err
	}

	return sessionIndex, nil
}

// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
// on /full/current while preserving other checkpoints' transcripts in the tree.
func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
	if err := s.ensureRef(refName); err != nil {
		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
	}

	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return err
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()
	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)

	// Read existing entries and replace transcript for this checkpoint only
	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return err
	}

	// Clear existing transcript entries at this session path before writing new ones
	for key := range entries {
		if strings.HasPrefix(key, sessionPath) {
			delete(entries, key)
		}
	}

	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
	if err != nil {
		return err
	}

	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
		return err
	}

	// Splice into existing root tree (preserves other checkpoints' transcripts)
	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return err
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
}

// writeCommittedMain writes metadata entries to the /main ref.
// This includes session metadata and prompts — but NOT the raw transcript
// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
	refName := plumbing.ReferenceName(paths.V2MainRefName)
	if err := s.ensureRef(refName); err != nil {
		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
	}

	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return 0, err
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()

	// Read existing entries at this checkpoint's shard path
	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return 0, err
	}

	// Build main session entries (metadata, prompts — no transcript or content hash)
	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
	if err != nil {
		return 0, err
	}

	// Splice entries into root tree
	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return 0, err
	}

	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
		return 0, err
	}
	return sessionIndex, nil
}

// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
// Returns the session index used, for coordination with writeCommittedFullTranscript.
func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
	// Read existing summary to get current session count
	var existingSummary *CheckpointSummary
	metadataPath := basePath + paths.MetadataFileName
	if entry, exists := entries[metadataPath]; exists {
		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
		if err == nil {
			existingSummary = existing
		}
	}

	// Determine session index
	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)

	// Write session files (metadata and prompts — no transcript or content hash)
	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
	if err != nil {
		return 0, err
	}

	// Build the sessions array
	var sessions []SessionFilePaths
	if existingSummary != nil {
		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
		copy(sessions, existingSummary.Sessions)
	} else {
		sessions = make([]SessionFilePaths, 1)
	}
	sessions[sessionIndex] = sessionFilePaths

	// Write root CheckpointSummary
	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
		return 0, err
	}
	return sessionIndex, nil
}

// writeMainSessionToSubdirectory writes a single session's metadata and prompts
// to a session subdirectory (0/, 1/, 2/, … indexed by session order within the
// checkpoint). Unlike the v1 equivalent, this does NOT write the raw transcript
// (full.jsonl) or content hash (content_hash.txt) — those go to /full/current.
func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
	filePaths := SessionFilePaths{}

	// Clear existing entries at this session path
	for key := range entries {
		if strings.HasPrefix(key, sessionPath) {
			delete(entries, key)
		}
	}

	// Write prompts
	if len(opts.Prompts) > 0 {
		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return filePaths, err
		}
		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
			Name: sessionPath + paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
	}

	// Write session metadata
	sessionMetadata := CommittedMetadata{
		CheckpointID:                opts.CheckpointID,
		SessionID:                   opts.SessionID,
		Strategy:                    opts.Strategy,
		CreatedAt:                   time.Now().UTC(),
		Branch:                      opts.Branch,
		CheckpointsCount:            opts.CheckpointsCount,
		FilesTouched:                opts.FilesTouched,
		Agent:                       opts.Agent,
		Model:                       opts.Model,
		TurnID:                      opts.TurnID,
		IsTask:                      opts.IsTask,
		ToolUseID:                   opts.ToolUseID,
		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
		TokenUsage:                  opts.TokenUsage,
		SessionMetrics:              opts.SessionMetrics,
		InitialAttribution:          opts.InitialAttribution,
		Summary:                     redactSummary(opts.Summary),
		CLIVersion:                  versioninfo.Version,
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
	if err != nil {
		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return filePaths, err
	}
	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
		Name: sessionPath + paths.MetadataFileName,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName

	return filePaths, nil
}

// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		return err
	}
	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
		Name: sessionPath + paths.ContentHashFileName,
		Mode: filemode.Regular,
		Hash: hashBlob,
	}
	return nil
}

// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
// Transcripts accumulate across checkpoints — each write splices into the existing
// tree. Generation metadata (generation.json) at the tree root is updated on every
// write with the new checkpoint ID and timestamps.
//
// sessionIndex is the session slot (0-based), determined by the caller to stay
// consistent with the /main ref's session numbering.
// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
	transcript := opts.Transcript
	if len(transcript) == 0 && opts.TranscriptPath != "" {
		var readErr error
		transcript, readErr = os.ReadFile(opts.TranscriptPath)
		if readErr != nil {
			transcript = nil
		}
	}
	if len(transcript) == 0 {
		return nil // No transcript to write
	}

	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
	if err := s.ensureRef(refName); err != nil {
		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
	}

	parentHash, rootTreeHash, err := s.getRefState(refName)
	if err != nil {
		return err
	}

	basePath := opts.CheckpointID.Path() + "/"
	checkpointPath := opts.CheckpointID.Path()
	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)

	// Read existing entries at this checkpoint's shard path
	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
	if err != nil {
		return err
	}

	// Clear existing entries at this session path before writing new ones
	for key := range entries {
		if strings.HasPrefix(key, sessionPath) {
			delete(entries, key)
		}
	}

	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
	if err != nil {
		return err
	}

	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
		return err
	}

	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
	if err != nil {
		return err
	}

	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
		return err
	}

	// Check if rotation is needed after successful write.
	// Count checkpoints by walking the tree (no generation.json on /full/current).
	checkpointCount, countErr := s.CountCheckpointsInTree(newTreeHash)
	if countErr != nil {
		logging.Warn(ctx, "failed to count checkpoints for rotation check",
			slog.String("error", countErr.Error()),
		)
		return nil
	}
	if checkpointCount >= s.maxCheckpoints() {
		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
			logging.Warn(ctx, "generation rotation failed",
				slog.String("error", rotErr.Error()),
				slog.Int("checkpoint_count", checkpointCount),
			)
			// Non-fatal: rotation failure doesn't invalidate the write
		}
	}

	return nil
}

// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
// Returns the redacted transcript bytes so the caller can compute the content hash.
func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
	// Redact secrets before chunking
	redacted, err := redact.JSONLBytes(transcript)
	if err != nil {
		return nil, fmt.Errorf("failed to redact transcript: %w", err)
	}

	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
	}

	for i, chunk := range chunks {
		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
		blobHash, err := CreateBlobFromContent(s.repo, chunk)
		if err != nil {
			return nil, err
		}
		entries[chunkPath] = object.TreeEntry{
			Name: chunkPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	return redacted, nil
}

// validateWriteOpts validates identifiers in WriteCommittedOptions.
func validateWriteOpts(opts WriteCommittedOptions) error {
	if opts.CheckpointID.IsEmpty() {
		return errors.New("invalid checkpoint options: checkpoint ID is required")
	}
	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	return nil
}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
// When a generation reaches this many checkpoints, it is archived
// and a fresh /full/current is created.
const DefaultMaxCheckpointsPerGeneration = 100

// GenerationMetadata tracks the state of a /full/* generation.
// Written to the tree root as generation.json at archive time only — not during
// normal writes to /full/current. This keeps /full/current free of root-level
// files, ensuring conflict-free tree merges during push recovery.
//
// The generation's sequence number is derived from the ref name, not stored here.
// Checkpoint membership is determined by walking the tree (shard directories).
type GenerationMetadata struct {
	// OldestCheckpointAt is the creation time of the earliest checkpoint.
	OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`

	// NewestCheckpointAt is the creation time of the most recent checkpoint.
	NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
}

// readGeneration reads generation.json from the given tree hash.
// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
func (s *V2GitStore) readGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
	if treeHash == plumbing.ZeroHash {
		return GenerationMetadata{}, nil
	}

	tree, err := s.repo.TreeObject(treeHash)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
	}

	file, err := tree.File(paths.GenerationFileName)
	if err != nil {
		if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
			return GenerationMetadata{}, nil
		}
		return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
	}

	content, err := file.Contents()
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
	}

	var gen GenerationMetadata
	if err := json.Unmarshal([]byte(content), &gen); err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
	}

	return gen, nil
}

// readGenerationFromRef reads generation.json from the tree pointed to by the given ref.
func (s *V2GitStore) readGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
	_, treeHash, err := s.getRefState(refName)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
	}
	return s.readGeneration(treeHash)
}

// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
// Returns a TreeEntry ready to be placed in a tree.
func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
	}

	blobHash, err := CreateBlobFromContent(s.repo, data)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
	}

	return object.TreeEntry{
		Name: paths.GenerationFileName,
		Mode: filemode.Regular,
		Hash: blobHash,
	}, nil
}

// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
	entry, err := s.marshalGenerationBlob(gen)
	if err != nil {
		return err
	}
	entries[paths.GenerationFileName] = entry
	return nil
}

// CountCheckpointsInTree counts checkpoint shard directories in a /full/* tree.
// The tree structure is <id[:2]>/<id[2:]>/ — we count second-level directories
// across all shard prefixes. Returns 0 for an empty tree.
func (s *V2GitStore) CountCheckpointsInTree(treeHash plumbing.Hash) (int, error) {
	if treeHash == plumbing.ZeroHash {
		return 0, nil
	}

	tree, err := s.repo.TreeObject(treeHash)
	if err != nil {
		return 0, fmt.Errorf("failed to read tree: %w", err)
	}

	count := 0
	for _, entry := range tree.Entries {
		if entry.Mode != filemode.Dir {
			continue // skip root-level files (e.g., generation.json on archived gens)
		}
		subtree, err := s.repo.TreeObject(entry.Hash)
		if err != nil {
			continue
		}
		for _, subEntry := range subtree.Entries {
			if subEntry.Mode == filemode.Dir {
				count++
			}
		}
	}

	return count, nil
}

// AddGenerationJSONToTree adds generation.json to an existing root tree, returning
// a new root tree hash. Preserves all existing entries (shard directories, etc.).
func (s *V2GitStore) AddGenerationJSONToTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
	entry, err := s.marshalGenerationBlob(gen)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
		UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
}

// computeGenerationTimestamps walks a /full/* tree and reads session metadata
// to determine the oldest and newest checkpoint timestamps.
func (s *V2GitStore) computeGenerationTimestamps(ctx context.Context, treeHash plumbing.Hash) (GenerationMetadata, error) {
	tree, err := s.repo.TreeObject(treeHash)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
	}

	var oldest, newest time.Time

	for _, shardEntry := range tree.Entries {
		if shardEntry.Mode != filemode.Dir {
			continue
		}
		shardTree, err := s.repo.TreeObject(shardEntry.Hash)
		if err != nil {
			continue
		}
		for _, cpEntry := range shardTree.Entries {
			if cpEntry.Mode != filemode.Dir {
				continue
			}
			cpTree, err := s.repo.TreeObject(cpEntry.Hash)
			if err != nil {
				continue
			}
			for _, sessionEntry := range cpTree.Entries {
				if sessionEntry.Mode != filemode.Dir {
					continue
				}
				sessionTree, err := s.repo.TreeObject(sessionEntry.Hash)
				if err != nil {
					continue
				}
				metaFile, err := sessionTree.File(paths.MetadataFileName)
				if err != nil {
					continue
				}
				content, err := metaFile.Contents()
				if err != nil {
					continue
				}
				var meta CommittedMetadata
				if err := json.Unmarshal([]byte(content), &meta); err != nil {
					continue
				}
				if !meta.CreatedAt.IsZero() {
					if oldest.IsZero() || meta.CreatedAt.Before(oldest) {
						oldest = meta.CreatedAt
					}
					if newest.IsZero() || meta.CreatedAt.After(newest) {
						newest = meta.CreatedAt
					}
				}
			}
		}
	}

	return GenerationMetadata{
		OldestCheckpointAt: oldest,
		NewestCheckpointAt: newest,
	}, nil
}

// generationRefWidth is the zero-padded width of archived generation ref names.
const generationRefWidth = 13

// generationRefPattern matches exactly 13 digits (the archived generation ref suffix format).
var generationRefPattern = regexp.MustCompile(`^\d{13}$`)

// listArchivedGenerations returns the names of all archived generation refs
// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
func (s *V2GitStore) ListArchivedGenerations() ([]string, error) {
	refs, err := s.repo.References()
	if err != nil {
		return nil, fmt.Errorf("failed to list references: %w", err)
	}

	var archived []string
	err = refs.ForEach(func(ref *plumbing.Reference) error {
		name := ref.Name().String()
		if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
			return nil
		}
		suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
		if suffix == "current" || !generationRefPattern.MatchString(suffix) {
			return nil
		}
		archived = append(archived, suffix)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to iterate references: %w", err)
	}

	sort.Strings(archived)
	return archived, nil
}

// nextGenerationNumber returns the next sequential generation number for archiving.
// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
func (s *V2GitStore) nextGenerationNumber() (int, error) {
	archived, err := s.ListArchivedGenerations()
	if err != nil {
		return 0, err
	}

	var maxNum int64
	for _, name := range archived {
		n, parseErr := strconv.ParseInt(name, 10, 64)
		if parseErr != nil {
			continue // skip unparseable entries
		}
		if n > maxNum {
			maxNum = n
		}
	}
	return int(maxNum) + 1, nil
}

// rotateGeneration archives the current /full/current generation and creates
// a fresh orphan. This is a 2-phase operation:
//
//  1. Archive: determine the next generation number, create a new ref pointing
//     to the current /full/current commit.
//  2. Reset: create a fresh orphan commit with an empty tree + seed generation.json,
//     point /full/current at it.
func (s *V2GitStore) rotateGeneration(ctx context.Context) error {
	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)

	// Guard against concurrent rotation: re-read /full/current and check if
	// it's still above the threshold. If not, another instance already rotated.
	_, currentTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return fmt.Errorf("rotation: failed to read /full/current: %w", err)
	}
	checkpointCount, err := s.CountCheckpointsInTree(currentTreeHash)
	if err != nil {
		return fmt.Errorf("rotation: failed to count checkpoints: %w", err)
	}
	if checkpointCount < s.maxCheckpoints() {
		return nil
	}

	currentRef, err := s.repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
	}

	archiveNumber, err := s.nextGenerationNumber()
	if err != nil {
		return fmt.Errorf("rotation: failed to determine next generation number: %w", err)
	}

	// Phase 1: Archive — create ref pointing to the current commit.
	// If the archive ref already exists, another instance already rotated — skip.
	archiveRefName := plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, archiveNumber))
	if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
		logging.Info(ctx, "rotation: archive ref already exists, skipping",
			slog.String("archive_ref", string(archiveRefName)),
		)
		return nil
	}
	archiveRef := plumbing.NewHashReference(archiveRefName, currentRef.Hash())
	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
		return fmt.Errorf("rotation: failed to create archived ref %s: %w", archiveRefName, err)
	}

	// Verify /full/current hasn't been advanced by another writer since we read it.
	// If it changed, abort — the archive ref is harmless (points to a valid commit)
	// and the next writer will trigger rotation again.
	postArchiveRef, err := s.repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
	}
	if postArchiveRef.Hash() != currentRef.Hash() {
		logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
		return nil
	}

	// Write generation.json to the current tree before archiving.
	gen, genErr := s.computeGenerationTimestamps(ctx, currentTreeHash)
	if genErr != nil {
		logging.Warn(ctx, "rotation: failed to compute generation timestamps",
			slog.String("error", genErr.Error()),
		)
		gen = GenerationMetadata{
			OldestCheckpointAt: time.Now().UTC(),
			NewestCheckpointAt: time.Now().UTC(),
		}
	}
	archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
	if err != nil {
		return fmt.Errorf("rotation: failed to add generation.json: %w", err)
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	archiveCommitHash, err := CreateCommit(s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("rotation: failed to create archive commit: %w", err)
	}

	// Update the archive ref to point to the commit with generation.json
	archiveRef = plumbing.NewHashReference(archiveRefName, archiveCommitHash)
	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
		return fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
	}

	// Phase 2: Create fresh orphan /full/current (empty tree, no generation.json)
	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return fmt.Errorf("rotation: failed to build empty tree: %w", err)
	}

	orphanCommitHash, err := CreateCommit(s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
	if err != nil {
		return fmt.Errorf("rotation: failed to create orphan commit: %w", err)
	}

	orphanRef := plumbing.NewHashReference(refName, orphanCommitHash)
	if err := s.repo.Storer.SetReference(orphanRef); err != nil {
		return fmt.Errorf("rotation: failed to reset /full/current: %w", err)
	}

	logging.Info(ctx, "generation rotation complete",
		slog.Int("archived_generation", archiveNumber),
		slog.String("archive_ref", string(archiveRefName)),
	)

	return nil
}

